def code_theme(name=None):
    "The pygments style to highlight code with under the named palette."
    return CODE_THEMES.get(name or ACTIVE_THEME, 'github-dark')

def code_bg(palette=None):
    """What a code block sits on. `bg1` per palette rather than one colour or the pygments style's
    own: a background chosen against a near-black canvas is invisible on `latte`, and a pygments
    style's own is whatever its author's editor was, which is not the terminal this is in."""
    return (palette or GRUVBOX)['bg1']

def set_theme(name='github-dark'):
    "Select the active semantic palette. `auto` safely falls back to the default in a terminal."
    global ACTIVE_THEME, GRUVBOX, MARKDOWN_THEME, GUTTERS
    name = str(name or 'github-dark').lower()
    if name == 'auto': name = 'github-dark'
    if name not in THEMES:
        raise ValueError(f"unknown theme {name!r}; choose auto or one of {', '.join(THEMES)}")
    GRUVBOX = THEMES[name]
    ACTIVE_THEME = name
    if '_theme_parts' in globals(): MARKDOWN_THEME, GUTTERS = _theme_parts(GRUVBOX)
    return name

