#: Terminals that speak kitty's graphics protocol, by what they put in the environment.
KITTY_ENV = ('KITTY_WINDOW_ID', 'GHOSTTY_RESOURCES_DIR')
KITTY_TERM = ('kitty', 'kaku', 'ghostty', 'wezterm')        # substrings of $TERM
KITTY_PROGRAM = ('WezTerm', 'Kaku', 'ghostty', 'kitty')     # exact $TERM_PROGRAM

def kitty_graphics():
    "Does this terminal speak the kitty graphics protocol?"
    if (forced := env('KITTY')) is not None:
        return str(forced).strip().lower() not in ('0', 'false', 'no', '')
    if any(os.environ.get(k) for k in KITTY_ENV): return True
    term, prog = os.environ.get('TERM', '').lower(), os.environ.get('TERM_PROGRAM', '')
    return any(t in term for t in KITTY_TERM) or prog in KITTY_PROGRAM

#: The box a picture is drawn in, how tall a cell is relative to its width, and how many one
#: turn may draw. Small and few on purpose: a tall block is what makes the transcript hard to
#: scroll, and a placement taller than the window can never have all of its rows on screen.
MAX_IMG_COLS = 24
MAX_IMG_ROWS = 12
CELL_ASPECT = 2.1
MAX_IMG_DRAW = 2
#: Rows a picture leaves the chrome around it: the tail, the path under it, the call above.
IMG_CHROME = 10

def png_size(path):
    "`(width, height)` in pixels from a PNG's IHDR, or `None`."
    try: b = Path(path).read_bytes()[:24]
    except OSError: return None
    if len(b) < 24 or b[:8] != b'\x89PNG\r\n\x1a\n': return None
    w, h = int.from_bytes(b[16:20], 'big'), int.from_bytes(b[20:24], 'big')
    return (w, h) if w and h else None

def img_cells(path, cols, rows=MAX_IMG_ROWS):
    """Cell width and height for `path` inside a `cols` by `rows` box, keeping its aspect.

    Both bounds matter. A tall screenshot at twenty-four columns wide is a hundred rows of
    block, and one taller than the window could never have all of its rows on screen at once --
    so it would fill the transcript and still never be drawn."""
    if not (wh := png_size(path)): return None
    w, h = wh
    c = max(1, min(cols, MAX_IMG_COLS))
    r = max(1, round(c * (h / w) / CELL_ASPECT))
    if r > (cap := max(1, min(rows, MAX_IMG_ROWS))): c, r = max(1, round(cap * CELL_ASPECT * w / h)), cap
    return c, r

APC_CHUNK = 4096

class Picture:
    """One picture on screen: bytes sent once, then re-placed at the end of every frame.

    Image ids are the terminal window's, not the process's, so the counter starts somewhere
    random: two sessions in the same window that both began at 1 would each replace the other's
    pictures, and kitty frees an image's placements with it -- including the ones in scrollback.
    """
    _n = randrange(1 << 20, 1 << 28)
    def __init__(self, path, cols=MAX_IMG_COLS, rows=MAX_IMG_ROWS):
        Picture._n += 1
        self.path, self.id, self.shown = Path(path), Picture._n, False
        self.cols, self.rows = img_cells(self.path, cols, rows) or (0, 0)

    def __bool__(self): return bool(self.rows)
    def __repr__(self): return f'Picture({self.path.name} {self.cols}x{self.rows})'

    def send(self):
        "The escape that hands the terminal the bytes, chunked as the protocol requires, drawing nothing."
        try: data = b64encode(self.path.read_bytes())
        except OSError: return ''
        out, head = [], f'a=t,f=100,i={self.id},q=2'
        for i in range(0, len(data), APC_CHUNK):
            more = int(i + APC_CHUNK < len(data))
            ctl = f'{head},m={more}' if not i else f'm={more}'
            out.append(f'\x1b_G{ctl};{data[i:i + APC_CHUNK].decode()}\x1b\\')
        return ''.join(out)

    def place(self):
        "The escape that draws it at the cursor. `C=1`: the cursor stays where the frame parked it."
        return f'\x1b_Ga=p,i={self.id},p=1,c={self.cols},r={self.rows},C=1,q=2\x1b\\'

    def clear(self):
        "The escape that takes the drawing off the screen, keeping the bytes for the next frame."
        return f'\x1b_Ga=d,d=i,i={self.id},p=1,q=2\x1b\\'

    def gap(self):
        """The rows the block reserves for it, the first of them naming the file.

        Blank text is the one thing a repaint can redraw, and the drawing lands on top of it: a
        kitty placement is drawn above the cells it covers, so the name is what shows only where
        the picture is not -- in the browsing view, in a fold's summary row, and in a terminal
        that took the bytes and drew nothing."""
        return Text(self.path.name + '\n' * (self.rows - 1), style=GRUVBOX['gray'])

def picture(path, cols=MAX_IMG_COLS, rows=MAX_IMG_ROWS):
    "A `Picture` for `path`, or None where this terminal or this file cannot be drawn."
    if not kitty_graphics() or Path(path).suffix.lower() != '.png': return None
    return p if (p := Picture(path, cols, rows)) else None

def draw_png(path, cols=MAX_IMG_COLS):
    "Send and place `path` at the cursor in one go, or `''`. For a caller with no frames to hook."
    return (p.send() + p.place()) if (p := picture(path, cols)) is not None else ''

def media_line(path):
    "What the transcript says about a saved picture: under the drawing, or in place of it."
    return str(path) if kitty_graphics() else f'saved  {path}'

